    fn account_snapshot_path(label: &str) -> PathBuf {
        let stamp = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        test_tmp_dir().join(format!(
            "chatgpt2api-rust-{label}-{}-{stamp}.json",
            std::process::id()
        ))
    }

    #[test]
    fn atomic_replace_reopens_write_only_temp_before_verification() {
        let path = account_snapshot_path("atomic-reopen-write-only");
        let parent = path.parent().expect("atomic replacement parent").to_owned();
        fs::write(&path, b"old\n").expect("initial atomic replacement target");

        atomic_replace_checked_with_limit(&path, b"new\n", 64, false)
            .expect("atomic replacement reopens a readable temporary handle");
        assert_eq!(
            fs::read(&path).expect("read committed atomic replacement"),
            b"new\n"
        );

        fs::remove_file(&path).expect("remove atomic replacement target");
        fs::remove_dir_all(parent).expect("remove atomic replacement parent");
    }

    #[test]
    fn account_snapshot_paths_isolate_parent_directory_rebinds() {
        let test_root = test_tmp_dir();
        let first = account_snapshot_path("parent-isolation-first");
        let second = account_snapshot_path("parent-isolation-second");
        let first_parent = first.parent().expect("first snapshot parent").to_owned();
        let second_parent = second.parent().expect("second snapshot parent").to_owned();

        assert!(first_parent.starts_with(&test_root.path));
        assert!(second_parent.starts_with(&test_root.path));
        assert_ne!(
            first_parent, second_parent,
            "tests that rebind a snapshot parent must not move another test's files"
        );

        fs::write(&first, b"[]").expect("first isolated snapshot");
        fs::write(&second, b"[]").expect("second isolated snapshot");
        let moved_first_parent = first_parent.with_extension("rebound");
        fs::rename(&first_parent, &moved_first_parent).expect("rebind first snapshot parent");
        assert_eq!(
            fs::read(&second).expect("second snapshot survives unrelated rebind"),
            b"[]"
        );

        fs::remove_dir_all(&moved_first_parent).expect("first isolation cleanup");
        fs::remove_dir_all(&second_parent).expect("second isolation cleanup");
    }

    fn test_cleanup_error_is_retryable(error: &io::Error) -> bool {
        matches!(
            error.kind(),
            io::ErrorKind::PermissionDenied | io::ErrorKind::WouldBlock
        ) || (cfg!(windows) && matches!(error.raw_os_error(), Some(5 | 32 | 33)))
    }

    async fn remove_test_file_after_release(path: &Path) {
        let deadline = Instant::now() + Duration::from_secs(2);
        loop {
            match fs::remove_file(path) {
                Ok(()) => return,
                Err(error) if error.kind() == io::ErrorKind::NotFound => return,
                Err(error)
                    if test_cleanup_error_is_retryable(&error) && Instant::now() < deadline =>
                {
                    tokio::task::yield_now().await;
                    tokio::time::sleep(Duration::from_millis(5)).await;
                }
                Err(error) => panic!("cleanup: {error}"),
            }
        }
    }

    async fn remove_test_directory_after_release(path: &Path) {
        let deadline = Instant::now() + Duration::from_secs(2);
        loop {
            match fs::remove_dir_all(path) {
                Ok(()) => return,
                Err(error) if error.kind() == io::ErrorKind::NotFound => return,
                Err(error)
                    if test_cleanup_error_is_retryable(&error) && Instant::now() < deadline =>
                {
                    tokio::task::yield_now().await;
                    tokio::time::sleep(Duration::from_millis(5)).await;
                }
                Err(error) => panic!("directory cleanup for {path:?}: {error}"),
            }
        }
    }

    #[test]
    fn public_search_urls_require_valid_percent_triplets() {
        assert!(normalize_public_search_url(&json!("https://example.test/%")).is_none());
        assert!(normalize_public_search_url(&json!("https://example.test/%A")).is_none());
        assert!(normalize_public_search_url(&json!("https://example.test/%GG")).is_none());
        assert_eq!(
            normalize_public_search_url(&json!("https://example.test/%20")),
            Some("https://example.test/%20".to_owned())
        );
    }

    fn test_account_jwt(account_id: &str, exp: i64, iat: i64) -> String {
        let payload = json!({
            "exp": exp,
            "iat": iat,
            "https://api.openai.com/auth": {"chatgpt_account_id": account_id}
        });
        let encoded = base64::engine::general_purpose::URL_SAFE_NO_PAD
            .encode(serde_json::to_vec(&payload).expect("JWT payload"));
        format!("e30.{encoded}.sig")
    }

    async fn json_response(response: Response) -> Value {
        let body = response
            .into_body()
            .collect()
            .await
            .expect("response body")
            .to_bytes();
        serde_json::from_slice(&body).expect("json response")
    }

