    #[tokio::test]
    async fn shutdown_forces_a_pending_connection_after_bounded_drain() {
        let request_started = Arc::new(Notify::new());
        let handler_notify = request_started.clone();
        let router = Router::new().route(
            "/hold",
            get(move || {
                handler_notify.notify_one();
                async { std::future::pending::<Response>().await }
            }),
        );
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("listener");
        let address = listener.local_addr().expect("address");
        let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel();
        let server = tokio::spawn(serve_with_bounded_shutdown(
            listener,
            router,
            async move {
                let _ = shutdown_rx.await;
            },
            Duration::from_millis(20),
        ));

        let mut connection = tokio::net::TcpStream::connect(address)
            .await
            .expect("connection");
        connection
            .write_all(b"GET /hold HTTP/1.1\r\nHost: localhost\r\n\r\n")
            .await
            .expect("request");
        request_started.notified().await;
        shutdown_tx.send(()).expect("shutdown");

        let mut server = server;
        assert!(
            tokio::time::timeout(Duration::from_millis(5), &mut server)
                .await
                .is_err()
        );
        let result = tokio::time::timeout(Duration::from_secs(1), server)
            .await
            .expect("bounded drain")
            .expect("server task");
        assert!(result.is_ok());
    }

    #[tokio::test]
    async fn state_shutdown_aborts_and_joins_editable_worker_owner() {
        let app_state = state(Some("client"));
        let workers = app_state.editable_workers.clone();
        let started = Arc::new(Notify::new());
        let worker_started = started.clone();
        assert!(
            workers
                .spawn(async move {
                    worker_started.notify_one();
                    std::future::pending::<()>().await;
                })
                .await
        );
        tokio::time::timeout(Duration::from_secs(1), started.notified())
            .await
            .expect("editable worker starts");
        assert_eq!(workers.active_for_test(), 1);

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("listener");
        let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel();
        let server = tokio::spawn(serve_state_with_bounded_shutdown(
            listener,
            app_state,
            async move {
                let _ = shutdown_rx.await;
            },
            Duration::from_secs(1),
        ));
        shutdown_tx.send(()).expect("shutdown");
        let result = tokio::time::timeout(Duration::from_secs(2), server)
            .await
            .expect("state shutdown")
            .expect("state server task");
        assert!(result.is_ok());
        assert_eq!(workers.active_for_test(), 0);
        assert!(!workers.spawn(async {}).await);
    }

    #[tokio::test]
    async fn shutdown_deadline_includes_blocked_owner_cleanup_without_detaching_it() {
        struct PendingCatalogOwnerGuard {
            running: Arc<AtomicBool>,
            canceled: Arc<Notify>,
        }

        impl Drop for PendingCatalogOwnerGuard {
            fn drop(&mut self) {
                self.running.store(false, Ordering::Release);
                self.canceled.notify_one();
            }
        }

        let app_state = state(Some("client"));
        let catalog = app_state.account_type_catalog.clone();
        let owner_started = Arc::new(Notify::new());
        let owner_canceled = Arc::new(Notify::new());
        catalog.refresh_running.store(true, Ordering::Release);
        let mut refresh_shutdown = catalog.refresh_shutdown.subscribe();
        let running = catalog.refresh_running.clone();
        let started = owner_started.clone();
        let canceled = owner_canceled.clone();
        let owner = tokio::spawn(async move {
            let _guard = PendingCatalogOwnerGuard { running, canceled };
            started.notify_one();
            tokio::select! {
                _ = refresh_shutdown.changed() => {}
                () = std::future::pending::<()>() => {}
            }
        });
        *catalog.refresh_task.lock().await = Some(owner);
        owner_started.notified().await;
        let cleanup_lock = catalog.refresh_task.lock().await;
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("listener");
        let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel();
        let mut server = tokio::spawn(serve_state_with_bounded_shutdown(
            listener,
            app_state,
            async move {
                let _ = shutdown_rx.await;
            },
            Duration::from_millis(20),
        ));

        let started = Instant::now();
        shutdown_tx.send(()).expect("shutdown");
        tokio::time::timeout(Duration::from_secs(1), async {
            while !catalog.shutdown_requested.load(Ordering::Acquire) {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("owner shutdown starts");
        let bounded_result = tokio::time::timeout(Duration::from_millis(200), &mut server).await;
        let returned_within_budget = match bounded_result {
            Ok(result) => {
                result.expect("server task").expect("server result");
                true
            }
            Err(_) => false,
        };
        let elapsed = started.elapsed();
        drop(cleanup_lock);
        if !returned_within_budget {
            tokio::time::timeout(Duration::from_secs(1), server)
                .await
                .expect("cleanup after red deadline")
                .expect("server task")
                .expect("server result");
        }

        assert!(
            returned_within_budget,
            "blocked owner cleanup escaped the 20ms drain deadline: {elapsed:?}"
        );
        tokio::time::timeout(Duration::from_millis(50), owner_canceled.notified())
            .await
            .expect("catalog owner canceled before bounded shutdown returns");
        assert!(
            tokio::time::timeout(Duration::from_millis(50), catalog.shutdown_taken.notified())
                .await
                .is_err(),
            "owner cleanup continued detached after bounded shutdown returned"
        );
        assert!(!catalog.refresh_running.load(Ordering::Acquire));
        let completed_owner = catalog
            .refresh_task
            .lock()
            .await
            .take()
            .expect("completed catalog owner remains joinable");
        assert!(completed_owner.is_finished());
        let _ = completed_owner.await;
    }

    #[tokio::test]
    async fn shutdown_signal_closes_http_admission_before_blocked_owner_cleanup() {
        async fn request_status(
            connection: &mut tokio::net::TcpStream,
            close: bool,
            timeout: Duration,
        ) -> Result<Option<u16>, &'static str> {
            let deadline = tokio::time::Instant::now() + timeout;
            let connection_header = if close { "close" } else { "keep-alive" };
            let request = format!(
                "GET /version HTTP/1.1\r\nHost: localhost\r\nConnection: {connection_header}\r\n\r\n"
            );
            match tokio::time::timeout_at(deadline, connection.write_all(request.as_bytes())).await
            {
                Err(_) => return Err("write timed out"),
                Ok(Err(_)) => return Ok(None),
                Ok(Ok(())) => {}
            }
            let mut response = Vec::new();
            loop {
                if let Some(header_end) = response.windows(4).position(|bytes| bytes == b"\r\n\r\n")
                {
                    let headers = std::str::from_utf8(&response[..header_end])
                        .map_err(|_| "non-UTF-8 HTTP headers")?;
                    let status = headers
                        .lines()
                        .next()
                        .and_then(|line| line.split_ascii_whitespace().nth(1))
                        .and_then(|status| status.parse::<u16>().ok())
                        .ok_or("malformed HTTP status")?;
                    let body_length = headers
                        .lines()
                        .skip(1)
                        .find_map(|line| {
                            let (name, value) = line.split_once(':')?;
                            name.eq_ignore_ascii_case("content-length")
                                .then(|| value.trim().parse::<usize>().ok())
                                .flatten()
                        })
                        .ok_or("missing content-length")?;
                    if response.len() >= header_end + 4 + body_length {
                        return Ok(Some(status));
                    }
                }
                if response.len() >= 64 * 1024 {
                    return Err("HTTP response exceeded test bound");
                }
                let mut chunk = [0_u8; 1024];
                match tokio::time::timeout_at(deadline, connection.read(&mut chunk)).await {
                    Err(_) => return Err("response timed out"),
                    Ok(Err(_)) => return Ok(None),
                    Ok(Ok(0)) if response.is_empty() => return Ok(None),
                    Ok(Ok(0)) => return Err("truncated HTTP response"),
                    Ok(Ok(read)) => response.extend_from_slice(&chunk[..read]),
                }
            }
        }

        let app_state = state(Some("client"));
        let admission_state = app_state.clone();
        let catalog = app_state.account_type_catalog.clone();
        let cleanup_lock = catalog.refresh_task.lock().await;
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("listener");
        let address = listener.local_addr().expect("address");
        let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel();
        let mut server = tokio::spawn(serve_state_with_bounded_shutdown(
            listener,
            app_state,
            async move {
                let _ = shutdown_rx.await;
            },
            Duration::from_secs(5),
        ));
        let mut connection = tokio::time::timeout(
            Duration::from_secs(5),
            tokio::net::TcpStream::connect(address),
        )
        .await
        .expect("startup connect deadline")
        .expect("startup connection");
        assert_eq!(
            request_status(&mut connection, false, Duration::from_secs(5)).await,
            Ok(Some(200)),
            "startup admission handshake"
        );

        shutdown_tx.send(()).expect("shutdown");
        tokio::time::timeout(Duration::from_secs(1), async {
            while admission_state.http_admission_open.load(Ordering::Acquire) {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("HTTP admission fence closes");
        let response_after_signal =
            request_status(&mut connection, true, Duration::from_secs(1)).await;
        drop(cleanup_lock);
        tokio::time::timeout(Duration::from_secs(1), &mut server)
            .await
            .expect("server shutdown")
            .expect("server task")
            .expect("server result");

        assert!(
            matches!(response_after_signal, Ok(None | Some(503))),
            "HTTP admission result while owner cleanup was blocked: {response_after_signal:?}"
        );
    }

    #[tokio::test]
    async fn http_admission_fence_rejects_new_requests() {
        let app_state = state(Some("client"));
        app_state.begin_http_shutdown();
        let response = app_state
            .router()
            .oneshot(
                axum::http::Request::builder()
                    .uri("/version")
                    .body(Body::empty())
                    .expect("request"),
            )
            .await
            .expect("response");
        assert_eq!(response.status(), StatusCode::SERVICE_UNAVAILABLE);
        assert_eq!(response.headers().get(header::RETRY_AFTER).unwrap(), "1");
        let body = to_bytes(response.into_body(), 4096).await.expect("body");
        let payload: Value = serde_json::from_slice(&body).expect("JSON error");
        assert_eq!(payload["error"]["code"], "server_shutting_down");
    }

    #[tokio::test]
    async fn shutdown_admission_fence_blocks_a_refresh_started_after_shutdown() {
        let account_path = test_tmp_dir().join(format!(
            "chatgpt2api-rust-catalog-shutdown-fence-{}-{}.json",
            std::process::id(),
            NATIVE_MESSAGE_ID.fetch_add(1, Ordering::Relaxed)
        ));
        fs::write(&account_path, b"[]").expect("account snapshot");
        let app_state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("client".to_owned()),
            models: vec!["static-model".to_owned()],
            upstream_base_url: Some("http://127.0.0.1:1".to_owned()),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path.clone()),
            upstream_protocol: UpstreamProtocol::ChatGpt,
        })
        .expect("state");
        let catalog = app_state.account_type_catalog.clone();
        let refresh_slot = catalog.refresh_task.lock().await;
        let shutdown_catalog = catalog.clone();
        let shutdown = tokio::spawn(async move {
            shutdown_catalog.shutdown().await;
        });
        tokio::task::yield_now().await;
        drop(refresh_slot);
        catalog.shutdown_taken.notified().await;

        let refresh_catalog = catalog.clone();
        let refresh = tokio::spawn(async move {
            refresh_catalog.refresh_with_cold_wait(None).await;
        });

        shutdown.await.expect("shutdown task");
        refresh.await.expect("refresh task");
        assert!(!catalog.refresh_running.load(Ordering::Acquire));
        assert!(catalog.refresh_task.lock().await.is_none());
        fs::remove_file(account_path).expect("cleanup");
    }

    #[tokio::test]
    async fn shutdown_cancels_background_catalog_refresh_owner() {
        let account_path = test_tmp_dir().join(format!(
            "chatgpt2api-rust-catalog-shutdown-{}-{}.json",
            std::process::id(),
            NATIVE_MESSAGE_ID.fetch_add(1, Ordering::Relaxed)
        ));
        fs::write(
            &account_path,
            r#"[{"access_token":"catalog-token","status":"正常","type":"free"}]"#,
        )
        .expect("account snapshot");

        let upstream_started = Arc::new(Notify::new());
        let upstream_release = Arc::new(Notify::new());
        let upstream_canceled = Arc::new(Notify::new());
        let upstream_ready = Arc::new(Notify::new());
        let completed_normally = Arc::new(AtomicBool::new(false));
        let started_for_upstream = upstream_started.clone();
        let release_for_upstream = upstream_release.clone();
        let canceled_for_upstream = upstream_canceled.clone();
        let completed_for_upstream = completed_normally.clone();
        let ready_for_upstream = upstream_ready.clone();
        let upstream_listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("upstream listener");
        let upstream_address = upstream_listener.local_addr().expect("upstream address");
        let upstream = tokio::spawn(async move {
            let root = get(move || {
                let started = started_for_upstream.clone();
                let release = release_for_upstream.clone();
                let canceled = canceled_for_upstream.clone();
                let completed = completed_for_upstream.clone();
                async move {
                    let _guard = CatalogRequestGuard {
                        completed_normally: completed.clone(),
                        canceled,
                    };
                    started.notify_one();
                    release.notified().await;
                    completed.store(true, Ordering::Release);
                    Html("<html></html>")
                }
            });
            let server = axum::serve(
                upstream_listener,
                Router::new()
                    .route("/", root.clone())
                    .route("/backend-api/models", root),
            );
            ready_for_upstream.notify_one();
            server.await.expect("upstream server");
        });
        upstream_ready.notified().await;

        let app_state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("client".to_owned()),
            models: vec!["static-model".to_owned()],
            upstream_base_url: Some(format!("http://{upstream_address}")),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: Some(account_path.clone()),
            upstream_protocol: UpstreamProtocol::ChatGpt,
        })
        .expect("state");
        assert!(app_state.account_type_catalog.enabled());
        app_state
            .account_type_catalog
            .set_codex_client_version_for_test(Some("0.147.0".to_owned()));
        let (_, active_account_groups) = app_state
            .account_store
            .active_type_candidates()
            .await
            .expect("account snapshot remains readable");
        assert_eq!(active_account_groups.len(), 1);
        app_state.account_type_catalog.refresh_for_public().await;
        tokio::time::timeout(Duration::from_secs(1), upstream_started.notified())
            .await
            .expect("catalog refresh must start before handoff");
        let app_listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("app listener");
        let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel();
        let app = tokio::spawn(serve_state_with_bounded_shutdown(
            app_listener,
            app_state,
            async move {
                let _ = shutdown_rx.await;
            },
            Duration::from_millis(20),
        ));

        shutdown_tx.send(()).expect("shutdown");
        tokio::time::timeout(Duration::from_secs(1), app)
            .await
            .expect("app shutdown")
            .expect("app task")
            .expect("server result");

        let canceled_before_release =
            tokio::time::timeout(Duration::from_millis(100), upstream_canceled.notified())
                .await
                .is_ok();
        upstream_release.notify_waiters();
        assert!(
            canceled_before_release,
            "catalog refresh must be canceled before shutdown returns"
        );

        upstream.abort();
        let _ = upstream.await;
        fs::remove_file(account_path).expect("cleanup");
    }

    #[tokio::test]
    async fn generic_chat_request_timeout_covers_response_headers() {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("listener");
        let address = listener.local_addr().expect("address");
        let server = tokio::spawn(async move {
            let (mut socket, _) = listener.accept().await.expect("connection");
            let mut request = [0u8; 4096];
            let _ = socket.read(&mut request).await;
            std::future::pending::<()>().await;
        });
        let app_state = AppState::new(AppConfig {
            version: "test".to_owned(),
            auth_key: Some("client".to_owned()),
            models: vec!["gpt-test".to_owned()],
            upstream_base_url: Some(format!("http://{address}")),
            upstream_auth: None,
            auth_keys_path: None,
            models_path: None,
            accounts_path: None,
            upstream_protocol: UpstreamProtocol::OpenAi,
        })
        .expect("state");
        let mut headers = HeaderMap::new();
        headers.insert(
            header::AUTHORIZATION,
            HeaderValue::from_static("Bearer client"),
        );
        let result = tokio::time::timeout(
            Duration::from_millis(100),
            chat_completions_with_timeout(
                State(app_state),
                headers,
                Body::from(r#"{"model":"gpt-test","prompt":"hello"}"#),
                Duration::from_millis(10),
            ),
        )
        .await
        .expect("request timeout must be observed by handler");
        assert!(result.is_err());
        server.abort();
    }

